   692  cs_err CAPSTONE_API cs_option(csh ud, cs_opt_type type, size_t value)
   693  {
   694          struct cs_struct *handle;
   695          cs_opt_mnem *opt;
   696
   697          // cs_option() can be called with NULL handle just for CS_OPT_MEM
   698          // This is supposed to be executed before all other APIs (even cs_open())
   699          if (type == CS_OPT_MEM) {
   700                  cs_opt_mem *mem = (cs_opt_mem *)value;
   701
   702                  cs_mem_malloc = mem->malloc;
   703                  cs_mem_calloc = mem->calloc;
   704                  cs_mem_realloc = mem->realloc;
   705                  cs_mem_free = mem->free;
   706                  cs_vsnprintf = mem->vsnprintf;
   707
   708                  return CS_ERR_OK;
   709          }
   710
   711          handle = (struct cs_struct *)(uintptr_t)ud;
   712          if (!handle)
   713                  return CS_ERR_CSH;
   714
   715          switch(type) {
   716                  default:
   717                          break;
   718
   719                  case CS_OPT_UNSIGNED:
   720                          handle->imm_unsigned = (cs_opt_value)value;
   721                          return CS_ERR_OK;
   722
   723                  case CS_OPT_DETAIL:
   724                          handle->detail = (cs_opt_value)value;
   725                          return CS_ERR_OK;
   726
   727                  case CS_OPT_SKIPDATA:
   728                          handle->skipdata = (value == CS_OPT_ON);
   729                          if (handle->skipdata) {
   730                                  if (handle->skipdata_size == 0) {
   731                                          // set the default skipdata size
   732                                          handle->skipdata_size = skipdata_size(handle);
   733                                  }
   734                          }
   735                          return CS_ERR_OK;
   736
   737                  case CS_OPT_SKIPDATA_SETUP:
   738                          if (value)
   739                                  handle->skipdata_setup = *((cs_opt_skipdata *)value);
   740                          return CS_ERR_OK;
   741
   742                  case CS_OPT_MNEMONIC:
   743                          opt = (cs_opt_mnem *)value;
   744                          if (opt->id) {
   745                                  if (opt->mnemonic) {
   746                                          struct insn_mnem *tmp;
   747
   748                                          // add new instruction, or replace existing instruction
   749                                          // 1. find if we already had this insn in the linked list
   750                                          tmp = handle->mnem_list;
   751                                          while(tmp) {
   752                                                  if (tmp->insn.id == opt->id) {
   753                                                          // found this instruction, so replace its mnemonic
   754                                                          (void)strncpy(tmp->insn.mnemonic, opt->mnemonic, sizeof(tmp->insn.mnemonic) - 1);
   755                                                          tmp->insn.mnemonic[sizeof(tmp->insn.mnemonic) - 1] = '\0';
   756                                                          break;
   757                                                  }
   758                                                  tmp = tmp->next;
   759                                          }
   760
   761                                          // 2. add this instruction if we have not had it yet
   762                                          if (!tmp) {
   763                                                  tmp = cs_mem_malloc(sizeof(*tmp));
   764                                                  tmp->insn.id = opt->id;
   765                                                  (void)strncpy(tmp->insn.mnemonic, opt->mnemonic, sizeof(tmp->insn.mnemonic) - 1);
   766                                                  tmp->insn.mnemonic[sizeof(tmp->insn.mnemonic) - 1] = '\0';
   767                                                  // this new instruction is heading the list
   768                                                  tmp->next = handle->mnem_list;
   769                                                  handle->mnem_list = tmp;
   770                                          }
   771                                          return CS_ERR_OK;
   772                                  } else {
   773                                          struct insn_mnem *prev, *tmp;
   774
   775                                          // we want to delete an existing instruction
   776                                          // iterate the list to find the instruction to remove it
   777                                          tmp = handle->mnem_list;
   778                                          prev = tmp;
   779                                          while(tmp) {
   780                                                  if (tmp->insn.id == opt->id) {
   781                                                          // delete this instruction
   782                                                          if (tmp == prev) {
   783                                                                  // head of the list
   784                                                                  handle->mnem_list = tmp->next;
   785                                                          } else {
   786                                                                  prev->next = tmp->next;
   787                                                          }
   788                                                          cs_mem_free(tmp);
   789                                                          break;
   790                                                  }
   791                                                  prev = tmp;
   792                                                  tmp = tmp->next;
   793                                          }
   794                                  }
   795                          }
   796                          return CS_ERR_OK;
   797
   798                  case CS_OPT_MODE:
