   800                          if (value & cs_arch_disallowed_mode_mask[handle->arch]) {
   801                                  return CS_ERR_OPTION;
   802                          }
   803                          break;
   804          }
   805
   806          return cs_arch_option[handle->arch](handle, type, value);
